INSERT INTO "blog_posts"
  ("id", "title", "slug", "content", "excerpt", "tags", "author", "status", "published_at")
VALUES
  (gen_random_uuid()::text, 'A CAPTCHA that wasn''t checking', 'a-captcha-that-wasn-t-checking', '<h2>What happened</h2><p>The widget showed on the forms and the secret was in the server''s settings, but the container never received it, so the check quietly accepted everything.</p><h2>What I changed</h2><p>I compared every environment variable the code reads with what the container is given, passed the missing one through, and added two one-line checks to the runbook.</p><h2>The lesson</h2><p>A control that looks switched on is not proof that it is.</p>', 'A control that looks switched on is not proof that it is.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '0 minutes'),
  (gen_random_uuid()::text, 'A deploy that failed safely', 'a-deploy-that-failed-safely', '<h2>What happened</h2><p>The registry login stored on the server had expired. The deploy stopped at the very first step, before anything changed, so the site never went down.</p><h2>What I changed</h2><p>I replaced the stored token with a short-lived login created for each deploy, and recorded the new version only after every step succeeded.</p><h2>The lesson</h2><p>Order steps so failure happens before change, and avoid credentials that expire unattended.</p>', 'Order steps so failure happens before change, and avoid credentials that expire unattended.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '1 minutes'),
  (gen_random_uuid()::text, '66,559 password guesses in a week', '66-559-password-guesses-in-a-week', '<h2>What happened</h2><p>The SSH logs showed constant automated guessing and not a single real password login.</p><h2>What I changed</h2><p>I turned password logins off, tested a fresh key login from a second window before closing the first, and documented how to get back in.</p><h2>The lesson</h2><p>Read the logs before you change anything, and always keep a way back.</p>', 'Read the logs before you change anything, and always keep a way back.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '2 minutes'),
  (gen_random_uuid()::text, 'A database open to the whole Wi-Fi', 'a-database-open-to-the-whole-wi-fi', '<h2>What happened</h2><p>A Docker port mapping without an address listens on every network interface. From the laptop''s network address I could log in to a development database.</p><h2>What I changed</h2><p>I bound it to localhost, proved the network address was now refused, and wrote the check up as a lesson in the repo.</p><h2>The lesson</h2><p>Prove the risk, then prove the fix.</p>', 'Prove the risk, then prove the fix.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '3 minutes'),
  (gen_random_uuid()::text, 'Restarting one container restarted its database', 'restarting-one-container-restarted-its-database', '<h2>What happened</h2><p>Compose recreated a dependency because its image tag had moved on. The data was safe on its volume, but the downtime was longer than planned.</p><h2>What I changed</h2><p>Every deploy step now uses --no-deps, and I verify the volume and the data afterwards.</p><h2>The lesson</h2><p>Know exactly what a command touches before you run it.</p>', 'Know exactly what a command touches before you run it.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '4 minutes'),
  (gen_random_uuid()::text, '"The site is down", but only for me', 'the-site-is-down-but-only-for-me', '<h2>What happened</h2><p>A new subdomain didn''t load on my laptop. My phone''s hotspot had cached a "doesn''t exist" answer from before I created the record.</p><h2>What I changed</h2><p>I wrote a layer-by-layer checklist (container, proxy, CDN, public DNS, my DNS), and a one-line command that skips DNS to isolate it.</p><h2>The lesson</h2><p>Change nothing until you know which layer is broken.</p>', 'Change nothing until you know which layer is broken.', ARRAY['Lessons learnt']::TEXT[], 'Bamise Omolaso', 'published', now() - interval '5 minutes')
